                      TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).
  Notation X4F' mm spl bd4 := (X4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm spl bd4).

  (* [comment removed for export] *)
  Variables (Q1 L1 v24 v32 v40 v72 v80 v96 v104 v120 v128 v136 v144 v152 c4 bc4 ptr4 st4 : Z) (j0 jp : list byte).
  Variables (y5 y12 y14 y15 y18 y20 y24 y25 y27 : word).
  Hypothesis HL1 : 1 <= L1 /\ 6 + L1 <= n.
  Hypothesis HQ1 : 0 < Q1 <= dcap.
  Notation SPL := (SPLY v24 v32 v40 (tl + 256 * mtl) (SS + 6) tl v72 v80 (DT + 4) v96 v104 (SS + 14) v120 v128 v136 v144 v152 j0).
  Notation BD := (BD4 c4 bc4 ptr4 st4 jp).

  Notation ST pc mm xra t1 t2 x8 x9 a0 a1 a3 a6 a7 x18 x19 x21 x22 x23 x26 x27 t3 t4 t5 t6 :=
    (MS (mkR xra (Z_to_bv 64 (SP + -416)) gp tp y5 t1 t2 x8 x9 a0 a1 y12 a3 y14 y15 a6 a7
             x18 x19 y20 x21 x22 x23 y24 y25 x26 x27 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  Hypothesis CONT : forall mm (xra x8 x9 a0 a1 a3 a6 a7 x19 t1 t2 t3 t4 : word),
